// ok(x)가 x <= 답일 때만 참이라고 할 때, 참인 가장 큰 x
int lo = 0, hi = 100;              // ok(lo)는 참
while (lo < hi) {
    int mid = (lo + hi + 1) / 2;   // 올림
    if (ok(mid)) lo = mid;
    else hi = mid - 1;
}
// 끝나면 lo == hi가 답

